import 'package:flutter/material.dart';
import 'package:google_maps_flutter/google_maps_flutter.dart';
import 'package:geolocator/geolocator.dart';
import '../models/user_address.dart';
import '../services/auth_service.dart';

class LocationSetupScreen extends StatefulWidget { const LocationSetupScreen({super.key}); @override State<LocationSetupScreen> createState() => _LocationSetupScreenState(); }
class _LocationSetupScreenState extends State<LocationSetupScreen> { LatLng pin = const LatLng(20.5937, 78.9629); final flat=TextEditingController(), area=TextEditingController(), landmark=TextEditingController(), code=TextEditingController(); Future<void> locate() async { if (!await Geolocator.isLocationServiceEnabled()) return; var p=await Geolocator.requestPermission(); if (p==LocationPermission.denied || p==LocationPermission.deniedForever) return; final x=await Geolocator.getCurrentPosition(); setState(() => pin=LatLng(x.latitude,x.longitude)); } void save() async { await AuthService.instance.saveAddress(UserAddress(flat: flat.text, area: area.text, landmark: landmark.text, pincode: code.text, latitude: pin.latitude, longitude: pin.longitude)); if (mounted) Navigator.pushReplacementNamed(context, '/home'); } @override Widget build(BuildContext c) => Scaffold(appBar: AppBar(title: const Text('Delivery address')), body: Column(children: [Expanded(flex: 2, child: GoogleMap(initialCameraPosition: CameraPosition(target: pin, zoom: 15), markers: {Marker(markerId: const MarkerId('address'), position: pin)}, onTap: (p) => setState(() => pin=p))), Expanded(child: ListView(padding: const EdgeInsets.all(16), children: [OutlinedButton.icon(onPressed: locate, icon: const Icon(Icons.my_location), label: const Text('Use my current location')), TextField(controller: flat, decoration: const InputDecoration(labelText: 'Flat / house no.')), const SizedBox(height: 10), TextField(controller: area, decoration: const InputDecoration(labelText: 'Area / street')), const SizedBox(height: 10), TextField(controller: landmark, decoration: const InputDecoration(labelText: 'Landmark')), const SizedBox(height: 10), TextField(controller: code, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Pincode')), const SizedBox(height: 14), FilledButton(onPressed: save, child: const Text('Save address'))]))])); }
